VALUES
  (NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'kosbling', 'mariclare', 'KOSBLING', 'Doll-craft kits', 'seed-thread-kosbling', 'active', 'Commission only', 'No fixed fee: 15% commission on net sales + gifted product (10% discount for your followers)', 'You own the content. Reposts/clips for 90 days only with our written OK. Paid/Spark ads need separate terms. No exclusivity.', 'Collaboration agreement (IO No. KOS-2026-10-14)', 'None (no pre-approval)', 'Late October or November', 'Paid through their ordinary payment process once sales are verified (no schedule)', 1, 'Contract signature promised by about Sun Oct 18, 2:45 PM', 'Kamron is deciding whether to sign as is or ask for a shorter bio-link term and a flat fee. No draft upload needed for this deal.', 0, 'Sign by Oct 18', 'c-red', 1, 1, '["1 TikTok, at least 30 seconds","Tag @kosblingcraft and #kosbling","Send the live link within 24 hours","Post stays up at least 90 days","KOSBLING referral link in your bio for the whole collab (Oct 14, 2026 to Oct 14, 2027)"]', '[["Sign contract by Oct 18","c-red"],["No pre-approval needed","c-gray"]]'),
  (NULL, 120000, 120000, 'VEV', 'https://www.canva.com/design/DAHTM5Yj-XQ/kX5plW6oPekkTDkc2DN2DA/edit', NULL, 0, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'vev', 'mariclare', 'VEV Gummies', 'Wellness gummies · via Haima Social', 'seed-thread-vev', 'active', '$1,200', '$1,200 + free product', '60-day Spark code. Exclusivity TBD. No contract seen yet.', 'Updated brief (Canva) sent Sat Oct 17, 12:00 AM', 'TBD (promised within a few days of Oct 16)', 'Sep–Oct 2026 per brand', 'TBD', 1, 'Draft promised "within the next few days" (Oct 16)', 'New brief arrived overnight. When you upload your draft here, I''ll write the email to VEV for Kamron to approve, then post their feedback back on this card.', 1, 'Draft in progress', 'c-sun', 1, 2, '["1 TikTok","60-day Spark code"]', '[["Draft due","c-sun"],["Brand approval before posting","c-gray"]]'),
  (NULL, 300000, 300000, 'WaterH (max)', NULL, NULL, 2, 'Upload revised draft (v2)', NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'waterh', 'mariclare', 'WaterH', 'Smart water bottle · repeat brand', 'seed-thread-waterh', 'active', 'Up to $3,000', 'Brand''s stated max: $3,000 for 3 videos (final figure TBD)', 'TBD', 'Revision notes from the brand (below)', 'Draft 1 sent Oct 13. Revision deadline TBD', 'TBD', 'Payment starts only after the videos are published', 1, 'Brand''s Oct 13–14 revision notes need a reply', 'WaterH asked for changes on Oct 13 and offered to do the extra edit themselves on Oct 14. Kamron is deciding: let them edit, or re-shoot the requested shots. Upload a new version here if you re-shoot.', 1, 'Revisions requested', 'c-red', 1, 3, '["3 videos","Later videos: add a spoken intro"]', '[["Revisions requested","c-red"],["3 videos","c-gray"]]'),
  (NULL, 180000, 180000, 'Persona', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'persona', 'mariclare', 'Persona', 'Organic integration', 'seed-thread-persona', 'negotiating', '$1,800', '$450 per post, $1,800 for 4 posts (earlier talks: $1,200, then $1,000 per post)', 'No paid media / no usage rights. Exclusivity TBD.', 'TBD', 'TBD', 'TBD (we asked)', 'Fully up front (date TBD)', 1, 'Kamron to send a clear yes or no on $450/post', 'Not confirmed yet. Don''t film until this card turns green.', 0, 'Negotiating', 'c-blue', 0, 4, '["4 posts, worked into your normal content (originally IG + TikTok crosspost)"]', '[["Negotiating","c-blue"],["Paid up front","c-sage"]]'),
  (NULL, 250000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'sanvive', 'mariclare', 'Sanvive', 'Smart towel warmer · Kickstarter launch', 'seed-thread-sanvive', 'negotiating', '$2,500', '$2,500 for TikTok only', '60-day worldwide license incl. paid ads + 60-day ad codes. 30-day exclusivity on towel warmers.', 'Contract (MSA + SOW) received Oct 14', '4 days after samples arrive (samples ship ~Oct 25, tentative)', '~Nov 15 (tentative)', '50% on draft approval, 50% on publication, each within 5 business days', 1, 'Waiting on the brand''s reply to our contract changes', 'Heads up: under their contract, posting 4+ days late, or posting early, loses the final 50%. I''ll remind you as soon as samples arrive.', 0, 'Contract in review', 'c-blue', 0, 5, '["1 TikTok, 20–60 seconds","Script, then a 4K draft","Up to 2 revisions","sanvive.com + Kickstarter link in bio","Post stays up 60 days"]', '[["Contract in review","c-blue"],["2 revisions included","c-gray"]]'),
  (NULL, 100000, NULL, NULL, 'https://docs.google.com/document/d/1bmlcofp_ureXxIqXL5KKGfdw-_yjNgy4E_NVJ6q7Jck/edit', NULL, NULL, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'halara', 'mariclare', 'Halara', 'Fall & Winter collection', 'seed-thread-halara', 'negotiating', '$1,000 + $500 GC', '$1,000 flat + $500 gift card', 'TBD (terms are in the contract, not received yet)', 'Updated brief (Google Doc)', 'TBD', 'Nov 15 (moved from Oct 15)', 'TBD', 1, 'Brand asked us to confirm and answer their questions (Oct 14)', 'Posting date is now Nov 15. Once Kamron confirms, I''ll ask Halara for the contract.', 1, 'Waiting on our confirmation', 'c-blue', 0, 6, '["1 TikTok on @_mariclaremaclamroc_ (fall decor / SAHM concept)","No view requirement"]', '[["Post Nov 15","c-sage"],["Waiting on our confirmation","c-blue"]]'),
  (NULL, NULL, NULL, NULL, NULL, 'Oct 16 agreement: payment on Grail-sourced deals routes to Grail first. Hidden from MariClare on purpose. Do not copy personal inbox items into this deal.', NULL, NULL, NULL, 1, '2026-10-17T18:00:00.000Z', '2026-10-17T18:00:00.000Z', 'grail', 'mariclare', 'Grail', 'Grail-sourced deals', 'seed-thread-grail', 'negotiating', 'Via Grail', 'Payment on Grail-sourced deals routes to Grail first', 'TBD', 'Oct 16 Grail agreement', 'TBD', 'TBD', 'Brand payment on Grail-sourced deals goes to Grail first', 0, 'Hidden from MariClare until you decide what she should see', 'This card is only on your admin view. MariClare cannot open it.', 0, 'Hidden from creator', 'c-gray', 0, 7, '["Hidden until Kamron decides what MariClare should see"]', '[["Hidden from creator","c-gray"]]');
